    function testFuzz_property(uint128 attackerAmt, uint128 victimAmt) public {
        // keep amounts in a sensible wide range but non-zero
        attackerAmt = uint128(bound(attackerAmt, 1, 1 ether));
        victimAmt = uint128(bound(victimAmt, 1, 1 ether));

        // deploy attacker helper that will re-enter withdraw during receive
