        // choose two distinct signers: attackerAddr and victimAddr
        address attackerAddr = address(attacker);
        address victimAddr = vm.addr(1);

        // fund the EOA victim and the attacker contract
        vm.deal(victimAddr, victimAmt);
        vm.deal(attackerAddr, attackerAmt);

        // victim deposits victimAmt into c via fallback
        vm.prank(victimAddr);
        (bool ok1, ) = address(c).call{value: victimAmt}('');
        require(ok1);

        // attacker deposits attackerAmt into c via fallback
        vm.prank(attackerAddr);
        (bool ok2, ) = address(c).call{value: attackerAmt}('');
        require(ok2);

        // record total stored balances by summing known entries: attacker and victim
        // Note: we can only read public getter balances(address)
        uint256 sumBefore = c.balances(attackerAddr) + c.balances(victimAddr);
        // Also the contract's actual ether balance
        uint256 balBefore = address(c).balance;

        // Sanity: for the correct contract, sumBefore should equal balBefore
        // We assert this later as the universal invariant. First drive the potentially-buggy behavior.

        // Now trigger withdraw from attacker which will try to re-enter into c.withdraw
        // Attacker contract's receive will re-enter and attempt to drain victim's balance if reentrancy is possible
        attacker.attackWithdraw();

        // After the attack, recompute the sum of balances for the two addresses and contract balance
        uint256 sumAfter = c.balances(attackerAddr) + c.balances(victimAddr);
        uint256 balAfter = address(c).balance;

        // The general invariant: total stored balances for all addresses equals contract balance.
        // We only observed two addresses, but the contract started with only these two deposits, so
        // their sum should equal contract balance for the correct contract. Check that.
        assertTrue(sumAfter == balAfter);
    }
}

