pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // Fuzz parameters: attacker initial deposit, victim deposit, attacker address seed (as uint160)
    function testFuzz_property(uint256 attackerAmt, uint256 victimAmt, uint160 attackerSeed) public {
        // Keep amounts reasonable and nonzero
        attackerAmt = bound(attackerAmt, 1, 1 ether);
        victimAmt = bound(victimAmt, 1, 1 ether);
        // Derive attacker EOA-like address for funding; we'll deploy an attacker contract below using this seed
        address attackerEOA = address(uint160(attackerSeed));
        vm.assume(attackerEOA != address(0));

        // Deploy a reentrant attacker helper that will, during its receive, call c.withdraw() again
        Attacker atk = new Attacker(c);

        // Addresses: victim is an arbitrary actor
        address victim = address(0xBEEF);

        // Fund attacker contract and victim externally
        vm.deal(address(atk), attackerAmt);
        vm.deal(victim, victimAmt);

        // Victim sends funds to contract C via fallback
        vm.prank(victim);
        (bool sentVictim,) = address(c).call{value: victimAmt}('');
        require(sentVictim);

        // Attacker sends funds to contract C via fallback (so balances[attacker] > 0)
        vm.prank(address(atk));
        (bool sentAtk,) = address(c).call{value: attackerAmt}('');
        require(sentAtk);

        // Snapshot balances mapping for an address that is NOT the caller: choose victim as the other key
        uint256 beforeVictimBalance = c.balances(victim);

        // Now have the attacker contract call withdraw() on c. The attacker contract is designed to re-enter
        // during the external call if the reentrancy guard is missing.
        vm.prank(address(atk));
        atk.attackWithdraw();

        // After the attacker-triggered withdraw finishes, the invariant we assert is:
        // the victim's stored balances in the correct contract C must remain equal to what they were before
        // (i.e., a withdraw by attacker must not modify victim's balances).
        // This reads c's public getter and will hold for the reference, but the mutant that removed the
        // reentrancy protection can change other keys and violate it for some inputs.
        assertTrue(c.balances(victim) == beforeVictimBalance);
    }
}

// Minimal re-entrant attacker helper. It holds funds and when calling withdraw it will re-enter
// C during the external call by performing another withdraw() call from its receive().
contract Attacker {
    C immutable target;
    bool reentered;

    constructor(C _target) {
        target = _target;
    }

    // Entry point used by the test to start the attack
    function attackWithdraw() external {
        // Call withdraw on target; during the external call, when target sends ether back to this contract,
        // receive() will be invoked and attempt a re-entrant withdraw() again.
        target.withdraw();
    }

    receive() external payable {
        // Only re-enter once to try to manipulate other stored balances
        if (!reentered) {
            reentered = true;
            // attempt to re-enter withdraw
            // ignore failures; we're interested in effects on target.balances
            (bool ok, ) = address(target).call(abi.encodeWithSignature("withdraw()"));
            // silence unused
            ok;
        }
    }
}

