pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters:
    // - attackerDeposit: amount attacker will deposit to set up reentrancy path
    // - victimDeposit: amount victim deposits
    // - attackerIs: whether the attacker is the special Attacker contract (1) or a plain EOA (0)
    // We need at least one parameter; use three to give fuzzer room.
    function testFuzz_property(uint256 attackerDeposit, uint256 victimDeposit, uint8 attackerIs) public {
        // keep amounts within reasonable bounds but wide
        attackerDeposit = bound(attackerDeposit, 1, 1 ether);
        victimDeposit = bound(victimDeposit, 1, 1 ether);
        attackerIs = attackerIs % 2; // 0 or 1

        // Deploy attacker helper when needed (attackerIs == 1). Always deploy to have an address to call.
        Attacker attacker = new Attacker(c);
        address payable attackerAddr = payable(address(attacker));
        address payable eoaAttacker = payable(address(uint160(0xABCD)));

        // Choose attacker address based on flag; if flag==0 use an EOA (no code) else use our Attacker contract
        address payable chosenAttacker = attackerIs == 1 ? attackerAddr : eoaAttacker;

        // Prepare victim as another EOA
        address payable victim = payable(address(uint160(0xBEEF)));

        // Fund the chosen attacker and victim in the test environment
        vm.deal(chosenAttacker, attackerDeposit + 1 ether);
        vm.deal(victim, victimDeposit + 1 ether);

        // Victim deposits to the contract by sending ether to fallback
        vm.prank(victim);
        (bool sentV, ) = address(c).call{value: victimDeposit}(
            ""
        );
        require(sentV);

        // Attacker deposits
        vm.prank(chosenAttacker);
        (bool sentA, ) = address(c).call{value: attackerDeposit}(
            ""
        );
        require(sentA);

        // We will sample a small set of addresses (victim, attacker, and two arbitrary addresses) and sum balances via public getter
        // Note: balances is public mapping(address => uint256) so c.balances(addr) is available
        uint256 before_sum = c.balances(victim) + c.balances(chosenAttacker) + c.balances(address(0x1)) + c.balances(address(0x2));

        // Now perform the withdraw as the victim. If attackerIs==1 the Attacker contract's receive will try to reenter during the victim's withdraw.
        vm.prank(victim);
        // call withdraw; it may succeed or revert depending on contract version; we ignore revert by try/catch
        bool ok;
        try c.withdraw{ }() {
            ok = true;
        } catch {
            ok = false;
        }

        // After withdraw returns (or reverts), compute the same sampled sum again
        uint256 after_sum = c.balances(victim) + c.balances(chosenAttacker) + c.balances(address(0x1)) + c.balances(address(0x2));

        // GENERAL RULE: For the correct contract, for every admissible inputs, after a victim withdraw the stored sum over these addresses never increases (no reentrant manipulation can create extra stored balances elsewhere).
        // The buggy mutant that removes the reentrancy lock can cause a reentrant attacker (our Attacker contract) to increase balances for other keys during the withdraw, making after_sum > before_sum for some inputs.
        assertTrue(after_sum <= before_sum);
    }
}

