pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    // fuzzed params: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor a non-zero address and amount bounded to avoid overflow in vm.deal
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether);

        // deploy a reverter helper that will reject any call (cause external call failures)
        Reverter rev = new Reverter();

        // fund depositor so they can call fallback to deposit
        vm.deal(depositor, amount);

        // depositor deposits ether into c via fallback
        vm.prank(depositor);
        (bool okDeposit,) = address(c).call{value: amount}("");
        require(okDeposit);

        // sanity: depositor's recorded balance should equal amount
        // read via public getter balances
        uint256 before = c.balances(depositor);
        require(before == amount);

        // Now attempt withdraw but direct the low-level call to our Reverter by making the caller be the Reverter contract.
        // The contract c calls msg.sender.call..., so we need msg.sender inside withdraw to be the reverter.
        // To achieve that, we make the reverter perform withdraw on behalf of depositor by using a helper that
        // forwards the call via a call from the reverter contract to c while msg.sender is the reverter.

        // transfer some gas/eth to reverter so it can call c (not strictly needed for empty call but safe)
        vm.deal(address(rev), 0);

        // make the reverter call withdraw on c. The withdraw will attempt a low-level call to msg.sender (the reverter)
        // which will revert in the Reverter implementation for the mutant scenario.
        // But we also need to ensure msg.sender of the withdraw is the depositor in the reference scenario.
        // To allow withdraw to operate on depositor's balances while msg.sender is the reverter, we first set up
        // the mapping so that balances[reverter] == amount and balances[depositor] == 0. To do that, we can have
        // the depositor deposit from the reverter address instead. Simpler: have the reverter perform the deposit,
        // then reverter will be the account with balance in c; then have reverter call withdraw. The fuzzer still
        // controls depositor and amount but we reuse depositor as funding source for the reverter.

        // fund the reverter from depositor
        // make depositor send amount to reverter so reverter can deposit into c
        vm.prank(depositor);
        (bool sentToRev,) = payable(address(rev)).call{value: amount}("");
        require(sentToRev);

        // reverter deposits into c (its fallback will increase balances[reverter])
        rev.depositTo{value: amount}(address(c));

        // ensure reverter's recorded balance is amount
        uint256 revBefore = c.balances(address(rev));
        require(revBefore == amount);

        // Now reverter calls withdraw on c; inside withdraw c will call msg.sender.call... where msg.sender == address(rev)
        bool okWithdraw;
        try rev.callWithdraw(address(c)) {
            okWithdraw = true;
        } catch {
            okWithdraw = false;
        }

        // The general property (single assertion): after withdraw returns (whether it reverted or not), the reference
        // contract guarantees that if withdraw completed successfully then the recorded balance for the caller is zero.
        // We assert that if the withdraw call returned (okWithdraw == true) then c.balances(rev) == 0.
        // This holds for the reference implementation for all inputs; the mutant will fail for some inputs because
        // its altered low-level call semantics can lead to differing post-state.
        assertTrue(!(okWithdraw) || c.balances(address(rev)) == 0);
    }
}

// adversarial helper that reverts on receive/fallback
contract Reverter {
    // allow contract to receive funds for depositing
    receive() external payable {}

    // helper to deposit into target contract by invoking its fallback
    function depositTo(address target) external payable {
        // forward funds to target, invoking fallback
        (bool ok, ) = target.call{value: msg.value}("");
        require(ok);
    }

    // call withdraw on target
    function callWithdraw(address target) external {
        // call withdraw so that inside target, msg.sender == address(this)
        C(target).withdraw();
    }

    // fallback that reverts to simulate a callee that rejects low-level calls
    fallback() external payable {
        revert("revert in fallback");
    }
}

// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // fuzz parameters: depositor address and amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero and amount bounded to avoid overflow/too large
        vm.assume(depositor != address(0));
        amount = bound(amount, 1, 1 ether);

        // deploy an adversarial callee that will REVERT on any call without value
        AdversarialCallee adv = new AdversarialCallee();

        // fund depositor so they can send value
        vm.deal(depositor, amount);

        // make depositor deposit into c by calling fallback (sending ETH)
        vm.prank(depositor);
        (bool okDeposit, ) = address(c).call{value: amount}(
            abi.encodeWithSignature("")
        );
        require(okDeposit);

        // sanity: recorded balance equals amount
        uint256 before = c.balances(depositor);
        assert(before == amount);

        // Now have depositor attempt withdraw but route the low-level call target to the adversarial contract
        // We achieve this by making the depositor be the adversarial contract (so msg.sender in c is adv)
        // First, transfer ownership of recorded balance to adv by making adv deposit same amount
        // (simulate adversarial actor being the one who deposited)
        vm.deal(address(adv), amount);
        vm.prank(address(adv));
        (bool okDeposit2, ) = address(c).call{value: amount}(abi.encodeWithSignature(""));
        require(okDeposit2);

        // confirm adversarial recorded balance
        uint256 advBefore = c.balances(address(adv));
        assert(advBefore == amount);

        // Now call withdraw as the adversarial callee (it will, in its fallback/receive, try to trigger the low-level behavior)
        // Use try/catch to capture success/failure of withdraw call itself
        bool ok;
        vm.prank(address(adv));
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // The universal property: if withdraw returned (ok == true) then recorded balance for that caller MUST be zero
        // This holds for the reference contract for all inputs. The mutant can cause the low-level call to fail
        // and may result in a different observed balance despite withdraw returning/behaving differently.
        if (ok) {
            assertTrue(c.balances(address(adv)) == 0);
        } else {
            // if withdraw reverted, nothing guaranteed about balances; we still must assert something true for reference
            // but reference will not revert here for the adversary that does not revert on receive; keep wide
            assertTrue(true);
        }
    }
}

// Adversarial callee: will revert on empty-call (simulate a callee that fails when called without value)
contract AdversarialCallee {
    // fallback without payable so calls without value revert; calls with value succeed (receive payable)
    fallback() external {
        revert("fail");
    }
    receive() external payable {}
}

