pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    // Fuzz parameters: depositor address and deposit amount
    function testFuzz_property(address depositor, uint256 amount) public {
        // keep depositor non-zero and amount within reasonable gas/eth bounds
        vm.assume(depositor != address(0));
        // bound amount to a workable range so vm.deal doesn't overflow funding
        amount = bound(amount, 1, 1 ether);

        // Deploy an adversarial callee that will revert when called (to simulate failing low-level call)
        Reverter bad = new Reverter();

        // Fund depositor and perform a deposit into c via fallback payable
        vm.deal(depositor, amount);
        vm.prank(depositor);
        // deposit: call fallback by sending value
        (bool okDeposit, ) = address(c).call{value: amount}(
            ""
        );
        require(okDeposit);

        // Now we want withdraw() to be invoked by a callee that causes the low-level call inside withdraw
        // to fail. The contract c does msg.sender.call{value: balances[msg.sender]}("");
        // To route c's external interaction through our Reverter, we have to make the depositor be the Reverter
        // But depositor is a fuzzed EOA; we instead simulate the scenario where msg.sender is the Reverter by
        // having the Reverter call withdraw. To keep parameters fuzzed, we still vary depositor and amount,
        // but use the Reverter as the caller when withdrawing. We first transfer the deposited balance record
        // onto the Reverter by making the depositor perform a deposit then transferring ownership of that
        // deposit record is impossible; instead, to create the adversarial failing callee scenario we make
        // the Reverter itself deposit and then call withdraw to trigger the failing external call.

        // So ensure Reverter has some ETH to deposit
        vm.deal(address(bad), amount);
        // Have the reverter deposit into c
        vm.prank(address(bad));
        (bool okDeposit2, ) = address(c).call{value: amount}("");
        require(okDeposit2);

        // Now the correct contract C will attempt to send value to msg.sender (the Reverter) during withdraw.
        // Our Reverter's fallback will revert, causing the low-level call to fail. In the reference contract,
        // the low-level call sends funds and balances[msg.sender] is set to 0 only after a successful send;
        // the mutant changes the call and may clear balances even when the send failed or behave differently.

        // Have the Reverter call withdraw
        vm.prank(address(bad));
        bool ok;
        try c.withdraw() {
            ok = true;
        } catch {
            ok = false;
        }

        // General rule to assert: if withdraw returned successfully then the recorded balance for the caller is zero.
        // We observe c through its public mapping getter balances(address)
        if (ok) {
            // exactly one assertion required
            assertTrue(c.balances(address(bad)) == 0);
        } else {
            // If withdraw reverted, we still assert the general rule vacuously by checking nothing — but we must have
            // exactly one assertTrue in the function. To satisfy that while keeping the universal property we only
            // assertTrue on the condition that matters (ok => balance==0). For the case ok==false we assert a true
            // literal would be invalid. Thus we structure the single assert as the implication expressed as a boolean.
            // This single assert covers both branches.
            assertTrue(!(ok) || (c.balances(address(bad)) == 0));
        }
