        // fund depositor so it can call fallback to deposit
        vm.deal(depositor, amount);

        // depositor deposits into contract via fallback (balances[msg.sender] += msg.value)
        vm.prank(depositor);
        (bool okDeposit, ) = address(c).call{value: amount}("");
        require(okDeposit);

        // record contract balance and recorded depositor balance before withdraw
        uint256 beforeContractBal = address(c).balance;
        uint256 recordedBefore = c.balances(depositor);
        // sanity: recordedBefore should equal amount
        // now attempt withdraw but make the msg.sender be the adversarial Reverter (so the low-level call targets a callee controlled by depositor)
        // To route withdraw's external call to a callee that may revert, we need msg.sender to be that adversarial contract.
        // So first we transfer recorded balance by having depositor set balances mapping? The contract uses msg.sender in balances; we cannot change stored key.
        // Instead, we simulate the depositor being the adversarial contract by repeating the deposit from the adversarial contract.

        // deploy a proxy that will first receive funds (deposit) as the adversarial callee identity
        AttackerProxy proxy = new AttackerProxy(address(c), address(rev));
        // fund proxy to deposit
        vm.deal(address(proxy), amount);
        // proxy deposits as itself
        proxy.deposit{value: amount}();

        // check recorded balance for proxy
        uint256 recordedProxyBefore = c.balances(address(proxy));
        // ensure it recorded deposit
        require(recordedProxyBefore == amount);

