        uint256 beforeContractBalProxy = address(c).balance;

        // proxy will call withdraw; its low-level call target inside withdraw is msg.sender (the proxy)
        // but withdraw does msg.sender.call{value: balances[msg.sender]}("") in reference; in mutant it does msg.sender.call("") with no value
        // We make the proxy's fallback/receive forward to the Reverter to force reverting on receiving value

        // Now invoke withdraw from proxy
        bool ok;
        try proxy.doWithdraw() {
            ok = true;
        } catch {
            ok = false;
        }

