}

// Helper attacker proxy: deposits and then calls withdraw; on receive it forwards to Reverter to force failure when value is sent
contract AttackerProxy {
    C public c;
    address public sink;
    constructor(address _c, address _sink) {
        c = C(_c);
        sink = _sink;
    }
    function deposit() external payable {
        // call fallback of C to deposit
        (bool ok, ) = address(c).call{value: msg.value}("");
        require(ok);
    }
    function doWithdraw() external {
        c.withdraw();
    }
    // fallback to forward any received funds to sink which will revert
    receive() external payable {
        // forward (with value) to sink; if sink reverts, this receive will revert
        (bool s, ) = sink.call{value: msg.value}("");
        require(s);
    }
}

